const TOOL_NAMES: Record<string, string> = {
  claude: 'Claude Code',
  codex: 'Codex',
  cursor: 'Cursor',
  kiro: 'Kiro',
  qoder: 'Qoder',
  codebuddy: 'CodeBuddy',
  shell: '终端',
};

function toolTitle(tool: string) {
  if (tool === 'shell' && typeof document !== 'undefined' && document.documentElement.lang === 'en') return 'Terminal';
  return TOOL_NAMES[tool] ?? tool;
}

function toolLogo(tool: string, gid: string) {
  switch (tool) {
    case 'claude':
      return (
        <>
          <path d={TILE} fill="#f6e9e2" />
          <path d={CLAUDE_CODE} fill="#d97757" transform="translate(3.6 3.6) scale(0.7)" />
        </>
      );
    case 'codex':
      return (
        <>
          <path d={TILE} fill="#fff" stroke="rgba(0,0,0,.12)" strokeWidth="0.6" />
          <path d={CODEX} fill="#000" fillRule="evenodd" transform="translate(3.6 3.6) scale(0.7)" />
        </>
      );
    case 'cursor':
      return (
        <>
          <path d={TILE} fill="#1b1b1b" />
          <path d={CURSOR} fill="#fff" fillRule="evenodd" transform="translate(4.2 4.2) scale(0.65)" />
        </>
      );
    case 'kiro':
      return (
        <>
          <path d={TILE} fill="#9046ff" />
          <path d={KIRO_BODY} fill="#fff" />
          <path d={KIRO_EYES} fill="#000" />
        </>
      );
    case 'qoder':
      return (
        <>
          <path d={TILE} fill="#111" />
          <g transform="translate(4 4) scale(0.667)">
            <path d={QODER_A} fill="#2ADB5C" />
            <path d={QODER_B} fill="#fff" />
          </g>
        </>
      );
    case 'codebuddy':
      return (
        <>
          <path d={TILE} fill={`url(#${gid})`} />
          <path d={CODEBUDDY} fill="#fff" transform="translate(2.4 2.4) scale(0.8)" />
          <defs>
            <radialGradient id={gid} cx="0" cy="0" r="1" gradientUnits="userSpaceOnUse" gradientTransform="matrix(-9 -16 16 -9 21 24.5)">
              <stop stopColor="#2EA99D" />
              <stop offset="1" stopColor="#6C4DFF" />
            </radialGradient>
          </defs>
        </>
      );
    default:
      return (
        <>
          <path d={TILE} fill="#8a8f98" />
          <path d="M6.5 8l4 4-4 4M12.5 16.5h5" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
        </>
      );
  }
}

/** Tool badge: each tool's own logo */
export function ToolBadge({ tool, size = 22 }: { tool: string; size?: number }) {
  // Each instance gets its own gradient id so multiple badges on a page don't interfere
  const gid = 'tb' + useId().replace(/:/g, '');
  return (
    <span className="tool-badge" style={{ width: size, height: size }} title={toolTitle(tool)}>
      <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true">
        {toolLogo(tool, gid)}
      </svg>
    </span>
  );
}
